package com.gbkhealthcare.billing;

import com.gbkhealthcare.auth.*;
import com.gbkhealthcare.patient.PatientVisit;
import com.gbkhealthcare.patient.PatientVisitRepository;
import org.springframework.http.HttpStatus;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import java.math.*;
import java.time.*;
import java.util.*;

@Service
public class BillingService {
 private static final ZoneId CLINIC_ZONE=ZoneId.of("Asia/Kolkata");
 private final StaffAccessService staffAccess; private final AdminAccountRepository admins; private final PatientVisitRepository visits;
 private final BillableServiceRepository services; private final BillableServicePriceRepository prices; private final BillingInvoiceRepository invoices;
 private final BillingInvoiceLineRepository lines; private final BillingPaymentRepository payments; private final BillingRefundRepository refunds;
 private final BillingAdjustmentRepository adjustments; private final BillingAuditEventRepository audit;
 public BillingService(StaffAccessService staffAccess,AdminAccountRepository admins,PatientVisitRepository visits,BillableServiceRepository services,BillableServicePriceRepository prices,BillingInvoiceRepository invoices,BillingInvoiceLineRepository lines,BillingPaymentRepository payments,BillingRefundRepository refunds,BillingAdjustmentRepository adjustments,BillingAuditEventRepository audit){this.staffAccess=staffAccess;this.admins=admins;this.visits=visits;this.services=services;this.prices=prices;this.invoices=invoices;this.lines=lines;this.payments=payments;this.refunds=refunds;this.adjustments=adjustments;this.audit=audit;}
 @Transactional(readOnly=true) public List<BillableServiceResponse> serviceCatalog(Jwt jwt,boolean all){if(all)admin(jwt);else staffAccess.requireRole(jwt,StaffRole.CHECKOUT);return services.findAllByOrderByCategoryAscNameAsc().stream().filter(s->all||s.isActive()).map(s->BillableServiceResponse.from(s,prices.findTopByService_IdOrderByVersionDesc(s.getId()).orElse(null))).toList();}
 @Transactional(readOnly=true) public List<ServicePriceResponse> priceHistory(Jwt jwt,Long serviceId){admin(jwt);if(services.findById(serviceId).isEmpty())throw notFound("Billable service not found.");return prices.findAllByService_IdOrderByVersionDesc(serviceId).stream().map(ServicePriceResponse::from).toList();}
 @Transactional public BillableServiceResponse createService(Jwt jwt,BillableServiceRequest request){AdminIdentity a=admin(jwt);if(services.findByCodeIgnoreCase(request.code().trim()).isPresent())throw conflict("Service code already exists.");LocalDateTime at=now();BillableService saved=services.save(new BillableService(request.code(),request.name(),request.description(),request.category(),at));record(null,"ADMIN",a.id,a.email,"SERVICE_CREATED","SERVICE",saved.getId(),at);return BillableServiceResponse.from(saved,null);}
 @Transactional public BillableServiceResponse updateService(Jwt jwt,Long id,BillableServiceRequest request){AdminIdentity a=admin(jwt);BillableService s=services.findByIdForUpdate(id).orElseThrow(()->notFound("Billable service not found."));services.findByCodeIgnoreCase(request.code().trim()).filter(other->!other.getId().equals(id)).ifPresent(other->{throw conflict("Service code already exists.");});s.updateDetails(request.code(),request.name(),request.description(),request.category());s=services.save(s);record(null,"ADMIN",a.id,a.email,"SERVICE_DETAILS_UPDATED","SERVICE",s.getId(),now());return BillableServiceResponse.from(s,prices.findTopByService_IdOrderByVersionDesc(id).orElse(null));}
 @Transactional public BillableServiceResponse setServiceActive(Jwt jwt,Long id,ServiceStatusRequest request){AdminIdentity a=admin(jwt);BillableService s=services.findByIdForUpdate(id).orElseThrow(()->notFound("Billable service not found."));s.setActive(request.active());s=services.save(s);LocalDateTime at=now();record(null,"ADMIN",a.id,a.email,s.isActive()?"SERVICE_ACTIVATED":"SERVICE_DEACTIVATED","SERVICE",s.getId(),at);return BillableServiceResponse.from(s,prices.findTopByService_IdOrderByVersionDesc(id).orElse(null));}
 @Transactional public BillableServiceResponse addPrice(Jwt jwt,Long id,ServicePriceRequest request){AdminIdentity a=admin(jwt);BillableService s=services.findByIdForUpdate(id).orElseThrow(()->notFound("Billable service not found."));int version=prices.countByService_Id(id)+1;LocalDateTime at=now();BillableServicePrice p=prices.save(new BillableServicePrice(s,version,money(request.amount()),request.taxRatePercent(),a.id,at));record(null,"ADMIN",a.id,a.email,"SERVICE_PRICE_CHANGED_V"+version,"SERVICE",id,at);return BillableServiceResponse.from(s,p);}
 @Transactional public InvoiceResponse createInvoice(Jwt jwt,Long visitId,InvoiceCreateRequest request){StaffAccount actor=staffAccess.requireRole(jwt,StaffRole.CHECKOUT);PatientVisit visit=visits.findByIdForBillingUpdate(visitId).orElseThrow(()->notFound("Encounter not found."));if(!"CONSULTATION_SIGNED".equals(visit.getEncounterStatus())||!"SIGNED".equals(visit.getConsultationStatus()))throw conflict("Billing can start only for a signed OPD encounter.");if(invoices.findFirstByPatientVisit_IdAndStatusNot(visitId,BillingInvoice.Status.VOID).isPresent())throw conflict("An active invoice already exists for this encounter.");LocalDateTime at=now();List<BillingInvoiceLine> lineItems=new ArrayList<>();BigDecimal subtotal=BigDecimal.ZERO,tax=BigDecimal.ZERO;
  for(InvoiceLineRequest r:request.lines()){BillableService s=services.findById(r.serviceId()).filter(BillableService::isActive).orElseThrow(()->notFound("Active billable service not found."));BillableServicePrice p=prices.findTopByService_IdOrderByVersionDesc(s.getId()).orElseThrow(()->conflict("Billable service has no configured price."));BillingInvoiceLine line=new BillingInvoiceLine(s,p,r.quantity());lineItems.add(line);subtotal=subtotal.add(money(line.getUnitPriceSnapshot().multiply(line.getQuantity())));tax=tax.add(line.getTaxAmountSnapshot());}
  subtotal=money(subtotal);tax=money(tax);BigDecimal discount=money(request.discountAmount());if(discount.compareTo(subtotal.add(tax))>0)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Discount cannot exceed the invoice subtotal and tax.");String number="GBK-"+UUID.randomUUID().toString().replace("-","").toUpperCase(Locale.ROOT);BillingInvoice invoice=new BillingInvoice(visit,number,subtotal,discount,tax,actor.getId(),at);lineItems.forEach(invoice::addLine);invoice=invoices.save(invoice);record(invoice.getId(),"CHECKOUT",actor.getId(),actor.getEmail(),"INVOICE_CREATED","INVOICE",invoice.getId(),at);return response(invoice);}
 @Transactional public InvoiceResponse issue(Jwt jwt,Long id){StaffAccount actor=staffAccess.requireRole(jwt,StaffRole.CHECKOUT);BillingInvoice i=lock(id);LocalDateTime at=now();try{i.issue();}catch(IllegalStateException e){throw conflict(e.getMessage());}i=invoices.save(i);record(i.getId(),"CHECKOUT",actor.getId(),actor.getEmail(),"INVOICE_ISSUED","INVOICE",i.getId(),at);return response(i);}
 @Transactional public InvoiceResponse voidDraft(Jwt jwt,Long id){StaffAccount actor=staffAccess.requireRole(jwt,StaffRole.CHECKOUT);BillingInvoice i=lock(id);try{i.voidDraft();}catch(IllegalStateException e){throw conflict(e.getMessage());}i=invoices.save(i);LocalDateTime at=now();record(i.getId(),"CHECKOUT",actor.getId(),actor.getEmail(),"INVOICE_VOIDED","INVOICE",i.getId(),at);return response(i);}
 @Transactional public InvoiceResponse recordPayment(Jwt jwt,Long id,PaymentRequest request){StaffAccount actor=staffAccess.requireRole(jwt,StaffRole.CHECKOUT);BillingInvoice i=lock(id);if(!List.of(BillingInvoice.Status.ISSUED,BillingInvoice.Status.PARTIALLY_PAID).contains(i.getStatus()))throw conflict("Payment can be recorded only against an issued invoice with a balance.");BigDecimal amount=money(request.amount());if(amount.compareTo(i.getOutstandingAmount())>0)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Payment exceeds the outstanding balance.");if(request.method()==BillingPayment.Method.OTHER&&(request.methodLabel()==null||request.methodLabel().isBlank()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Specify the Other payment method label.");if(request.method()!=BillingPayment.Method.OTHER&&request.methodLabel()!=null&&!request.methodLabel().isBlank())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"A custom method label is allowed only for Other.");requireSafeReference(request.paymentReference());LocalDateTime at=now();BillingPayment payment=payments.save(new BillingPayment(i,receiptNumber(),amount,request.method(),request.methodLabel(),request.paymentReference(),actor.getId(),at));recalculate(i,at);i=invoices.save(i);record(i.getId(),"CHECKOUT",actor.getId(),actor.getEmail(),"PAYMENT_RECORDED","PAYMENT",payment.getId(),at);return response(i);}
 @Transactional public RefundResponse refund(Jwt jwt,Long invoiceId,Long paymentId,RefundRequest request){StaffAccount actor=staffAccess.requireRole(jwt,StaffRole.CHECKOUT);BillingInvoice i=lock(invoiceId);BillingPayment p=payments.findById(paymentId).filter(x->x.getInvoice().getId().equals(invoiceId)).orElseThrow(()->notFound("Payment not found for this invoice."));BigDecimal prior=refunds.findAllByPayment_IdOrderByRefundedAtAsc(paymentId).stream().map(BillingRefund::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal amount=money(request.amount());if(amount.compareTo(p.getAmount().subtract(prior))>0)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Refund exceeds the refundable payment amount.");requireSafeReference(request.refundReference());LocalDateTime at=now();BillingRefund saved=refunds.save(new BillingRefund(p,amount,request.reason(),request.refundReference(),actor.getId(),at));recalculate(i,at);invoices.save(i);reopenIfBalance(i,actor,at);record(i.getId(),"CHECKOUT",actor.getId(),actor.getEmail(),"PAYMENT_REFUNDED","REFUND",saved.getId(),at);return RefundResponse.from(saved);}
 @Transactional public InvoiceResponse adjust(Jwt jwt,Long id,AdjustmentRequest request){StaffAccount actor=staffAccess.requireRole(jwt,StaffRole.CHECKOUT);BillingInvoice i=lock(id);if(i.getStatus()==BillingInvoice.Status.DRAFT||i.getStatus()==BillingInvoice.Status.VOID)throw conflict("Only an issued invoice can be adjusted.");BigDecimal amount=money(request.amount());if(amount.signum()==0)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Adjustment must change the invoice balance.");BigDecimal existing=adjustments.findAllByInvoice_IdOrderByCreatedAtAsc(id).stream().map(BillingAdjustment::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal projected=i.getSubtotal().add(i.getTaxAmount()).subtract(i.getDiscountAmount()).add(existing).add(amount);if(projected.signum()<0||projected.compareTo(i.getPaidAmount())<0)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Adjustment cannot reduce invoice total below zero or already-paid value.");LocalDateTime at=now();BillingAdjustment adj=adjustments.save(new BillingAdjustment(i,amount,request.reason(),actor.getId(),at));recalculate(i,at);invoices.save(i);reopenIfBalance(i,actor,at);record(i.getId(),"CHECKOUT",actor.getId(),actor.getEmail(),"INVOICE_ADJUSTED","ADJUSTMENT",adj.getId(),at);return response(i);}
 @Transactional(readOnly=true) public List<InvoiceResponse> encounterHistory(Jwt jwt,Long visitId){StaffAccount actor=staffAccess.requireRole(jwt,StaffRole.CHECKOUT);return invoices.findAllByPatientVisit_IdOrderByInvoiceDateDesc(visitId).stream().map(this::response).toList();}
 @Transactional(readOnly=true) public List<InvoiceResponse> outstanding(Jwt jwt){staffAccess.requireRole(jwt,StaffRole.CHECKOUT);return invoices.findAllByStatusInOrderByInvoiceDateAsc(List.of(BillingInvoice.Status.ISSUED,BillingInvoice.Status.PARTIALLY_PAID)).stream().map(this::response).toList();}
 @Transactional(readOnly=true) public List<CheckoutQueueItemResponse> checkoutQueue(Jwt jwt){staffAccess.requireRole(jwt,StaffRole.CHECKOUT);return visits.findAllByConsultationStatusAndCheckoutStatusOrderByCreatedAtAsc("SIGNED","PENDING").stream().map(this::checkoutItem).toList();}
 @Transactional public InvoiceResponse completeCheckout(Jwt jwt,Long id){StaffAccount actor=staffAccess.requireRole(jwt,StaffRole.CHECKOUT);BillingInvoice i=lock(id);PatientVisit visit=visits.findByIdForBillingUpdate(i.getPatientVisit().getId()).orElseThrow(()->notFound("Encounter not found."));List<String> blockers=checkoutBlockers(visit,i);if(!blockers.isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,String.join(" ",blockers));LocalDateTime at=now();visit.setCheckoutStatus("COMPLETE");visit.setCheckoutCompletedAt(at);visit.setCheckoutCompletedByStaffId(actor.getId());visits.save(visit);record(i.getId(),"CHECKOUT",actor.getId(),actor.getEmail(),"CHECKOUT_COMPLETED","ENCOUNTER",visit.getId(),at);return response(i);}
 @Transactional(readOnly=true) public List<BillingAuditEvent> audit(Jwt jwt,Long invoiceId){staffAccess.requireRole(jwt,StaffRole.CHECKOUT);return audit.findAllByInvoiceIdOrderByOccurredAtAscIdAsc(invoiceId);}
 @Transactional public InvoiceResponse approveDiscount(Jwt jwt,Long id,boolean approved){AdminIdentity a=admin(jwt);BillingInvoice i=lock(id);LocalDateTime at=now();try{i.approveDiscount(a.id,at,approved);}catch(IllegalStateException e){throw conflict(e.getMessage());}i=invoices.save(i);record(i.getId(),"ADMIN",a.id,a.email,approved?"DISCOUNT_APPROVED":"DISCOUNT_REJECTED","INVOICE",i.getId(),at);return response(i);}
 @Transactional(readOnly=true) public List<InvoiceResponse> adminInvoices(Jwt jwt){admin(jwt);return invoices.findAllByOrderByInvoiceDateDesc().stream().map(this::response).toList();}
 private void recalculate(BillingInvoice i,LocalDateTime at){List<BillingPayment> ps=payments.findAllByInvoice_IdOrderByPaidAtAsc(i.getId());BigDecimal paid=BigDecimal.ZERO;for(BillingPayment p:ps){BigDecimal returned=refunds.findAllByPayment_IdOrderByRefundedAtAsc(p.getId()).stream().map(BillingRefund::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);paid=paid.add(p.getAmount().subtract(returned));}BigDecimal adj=adjustments.findAllByInvoice_IdOrderByCreatedAtAsc(i.getId()).stream().map(BillingAdjustment::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);i.updateBalances(money(paid),money(adj),at);}
 private void reopenIfBalance(BillingInvoice i,StaffAccount actor,LocalDateTime at){if(i.getOutstandingAmount().signum()>0&&"COMPLETE".equals(i.getPatientVisit().getCheckoutStatus())){i.getPatientVisit().setCheckoutStatus("PENDING");record(i.getId(),"CHECKOUT",actor.getId(),actor.getEmail(),"CHECKOUT_REOPENED_BALANCE","ENCOUNTER",i.getPatientVisit().getId(),at);}}
 private static void requireSafeReference(String value){if(value==null||value.isBlank())return;String compact=value.replaceAll("[\\s-]","");if(compact.matches(".*\\d{13,}.*")||value.matches("(?is).*\\b(cvv|cvc|pin|password|secret|card\\s+number|security\\s+code)\\b.*"))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Payment references must not contain card or banking credentials.");}
 private InvoiceResponse response(BillingInvoice i){List<BillingPayment> ps=payments.findAllByInvoice_IdOrderByPaidAtAsc(i.getId());List<RefundResponse> rs=ps.stream().flatMap(p->refunds.findAllByPayment_IdOrderByRefundedAtAsc(p.getId()).stream()).map(RefundResponse::from).toList();return InvoiceResponse.from(i,lines.findAllByInvoice_IdOrderByIdAsc(i.getId()),ps,rs,adjustments.findAllByInvoice_IdOrderByCreatedAtAsc(i.getId()));}
 private BillingInvoice lock(Long id){return invoices.findByIdForUpdate(id).orElseThrow(()->notFound("Invoice not found."));}
 private CheckoutQueueItemResponse checkoutItem(PatientVisit visit){BillingInvoice invoice=invoices.findFirstByPatientVisit_IdAndStatusNot(visit.getId(),BillingInvoice.Status.VOID).orElse(null);BigDecimal refunded=BigDecimal.ZERO,adjustment=BigDecimal.ZERO;String invoiceStatus=null,number=null;Long invoiceId=null;BigDecimal total=BigDecimal.ZERO,paid=BigDecimal.ZERO,outstanding=BigDecimal.ZERO;if(invoice!=null){invoiceId=invoice.getId();number=invoice.getInvoiceNumber();invoiceStatus=invoice.getStatus().name();total=invoice.getTotal();paid=invoice.getPaidAmount();outstanding=invoice.getOutstandingAmount();for(BillingPayment p:payments.findAllByInvoice_IdOrderByPaidAtAsc(invoice.getId()))refunded=refunded.add(refunds.findAllByPayment_IdOrderByRefundedAtAsc(p.getId()).stream().map(BillingRefund::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add));adjustment=adjustments.findAllByInvoice_IdOrderByCreatedAtAsc(invoice.getId()).stream().map(BillingAdjustment::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);}List<String> blockers=checkoutBlockers(visit,invoice);return new CheckoutQueueItemResponse(visit.getId(),visit.getPatient().getId(),visit.getPatient().getFullName(),visit.getPatient().getPhone(),visit.getVisitDate(),visit.getAssignedDoctor()==null?visit.getDoctor():visit.getAssignedDoctor().getFullName(),visit.getConsultationSignedAt(),visit.getConsultationStatus(),visit.getCheckoutStatus(),invoiceId,number,invoiceStatus,total,paid,refunded,adjustment,outstanding,blockers.isEmpty(),blockers);}
 private List<String> checkoutBlockers(PatientVisit visit,BillingInvoice invoice){List<String> blockers=new ArrayList<>();if(!"SIGNED".equals(visit.getConsultationStatus())||visit.getConsultationSignedAt()==null)blockers.add("Consultation must be signed.");if(invoice==null)blockers.add("An invoice must be created and issued.");else{if(invoice.getStatus()==BillingInvoice.Status.DRAFT||invoice.getStatus()==BillingInvoice.Status.VOID)blockers.add("Invoice must be issued.");if(invoice.getStatus()!=BillingInvoice.Status.PAID||invoice.getOutstandingAmount().signum()!=0)blockers.add("Outstanding balance must be zero.");}if("COMPLETE".equals(visit.getCheckoutStatus()))blockers.add("Checkout has already been completed.");return blockers;}
 private AdminIdentity admin(Jwt jwt){if(jwt==null||jwt.getSubject()==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Admin authentication is required.");AdminAccount a=admins.findByEmailIgnoreCase(jwt.getSubject()).filter(AdminAccount::isEnabled).orElseThrow(()->new ResponseStatusException(HttpStatus.FORBIDDEN,"Active Admin account not found."));return new AdminIdentity(a.getId(),a.getEmail());}
 private void record(Long invoiceId,String role,Long actor,String email,String action,String resource,Long id,LocalDateTime at){audit.save(new BillingAuditEvent(invoiceId,role,actor,email,action,resource,id,at));}
 private static String receiptNumber(){return "REC-"+UUID.randomUUID().toString().replace("-","").toUpperCase(Locale.ROOT);} private static BigDecimal money(BigDecimal v){return v.setScale(2,RoundingMode.HALF_UP);} private static LocalDateTime now(){return LocalDateTime.now(CLINIC_ZONE);} private static ResponseStatusException conflict(String s){return new ResponseStatusException(HttpStatus.CONFLICT,s);} private static ResponseStatusException notFound(String s){return new ResponseStatusException(HttpStatus.NOT_FOUND,s);} private record AdminIdentity(Long id,String email){}
}
